const p = State.variables.player;
return JSON.stringify({
  player_keys: Object.keys(p.core_traits || p),
  has_frank_stage: 'npc_frank_stage' in (p.core_traits || p),
  flags_starter: Object.keys(State.variables.flags || {}).filter(k => k.startsWith('frank_')).slice(0, 20),
}, null, 2);

const SC = window.SugarCube || window.SC || (window.parent && window.parent.SugarCube);
if (!SC) return JSON.stringify({err: 'no SugarCube'});
const p = SC.State.variables.player;
const flags = SC.State.variables.flags || {};
return JSON.stringify({
  player_keys: Object.keys(p.core_traits || p),
  has_frank_stage: 'npc_frank_stage' in (p.core_traits || p),
  frank_flags: Object.keys(flags).filter(k => k.startsWith('frank_')),
}, null, 2);

const SC = window.SugarCube;
const v = SC.State.variables;
// Simulate post-crack state: set capstone flags + corruption + Frank traits
v.flags.frank_offered_bookkeeping = true;
v.flags.frank_caught = true;
v.flags.frank_restrict_declared = true;
v.flags.frank_cracked = true;
v.flags.frank_supervision_explained = true;
v.player.core_traits.corruption = 40;
v.npcs.npc_frank.core_traits.arousal = 30;
v.npcs.npc_frank.core_traits.corruption = 15;
v.npcs.npc_frank.core_traits.trust = 20;
return JSON.stringify({
  flags_set: ['frank_offered_bookkeeping', 'frank_caught', 'frank_restrict_declared', 'frank_cracked'].map(k => [k, v.flags[k]]),
  corruption: v.player.core_traits.corruption,
  frank: v.npcs.npc_frank.core_traits,
}, null, 2);

const SC = window.SugarCube;
const v = SC.State.variables;
return JSON.stringify({
  npcs_keys: Object.keys(v.npcs || {}),
  sample_npc: v.npcs && v.npcs.npc_frank ? Object.keys(v.npcs.npc_frank) : null,
}, null, 2);

const SC = window.SugarCube;
const v = SC.State.variables;
return JSON.stringify({
  npcs_keys: Object.keys(v.npcs || {}),
  npc_frank_keys: v.npcs && v.npcs.npc_frank ? Object.keys(v.npcs.npc_frank) : null,
  npc_frank_sample: v.npcs && v.npcs.npc_frank,
}, null, 2);

const SC = window.SugarCube;
const v = SC.State.variables;
const flags = v.flags;
// Manually evaluate the kitchen-morning S0/S1/S2/S3-pre/S3-post/S4 group gates
// for current flag state (post-crack: caught, restrict, cracked all true; invitation false)
const gateResults = {
  state: {
    offered_bookkeeping: flags.frank_offered_bookkeeping,
    caught: flags.frank_caught,
    restrict_declared: flags.frank_restrict_declared,
    cracked: flags.frank_cracked,
    invited: flags.frank_invited_to_bedroom,
    first_office_sex_done: flags.frank_office_first_sex_done,
  },
  s0_fires:       !flags.frank_caught,
  s1_fires:       flags.frank_offered_bookkeeping && !flags.frank_caught,
  s2_fires:       flags.frank_restrict_declared && !flags.frank_cracked,
  s3_pre_fires:   flags.frank_cracked && !flags.frank_invited_to_bedroom && !flags.frank_office_first_sex_done,
  s3_post_fires:  flags.frank_cracked && !flags.frank_invited_to_bedroom && flags.frank_office_first_sex_done,
  s4_fires:       flags.frank_invited_to_bedroom,
};
return JSON.stringify(gateResults, null, 2);

const SC = window.SugarCube;
const v = SC.State.variables;
v.flags.frank_invited_to_bedroom = true;
v.flags.frank_office_first_sex_done = true;
const flags = v.flags;
const fires = {
  s0:      !flags.frank_caught,
  s1:      flags.frank_offered_bookkeeping && !flags.frank_caught,
  s2:      flags.frank_restrict_declared && !flags.frank_cracked,
  s3_pre:  flags.frank_cracked && !flags.frank_invited_to_bedroom && !flags.frank_office_first_sex_done,
  s3_post: flags.frank_cracked && !flags.frank_invited_to_bedroom && flags.frank_office_first_sex_done,
  s4:      flags.frank_invited_to_bedroom,
};
const fired = Object.entries(fires).filter(([_,v]) => v).map(([k,_]) => k);
return JSON.stringify({ fired_groups: fired, all: fires }, null, 2);

const SC = window.SugarCube;
const flags = SC.State.variables.flags;
return JSON.stringify({
  fired_groups: [
    ['s0', !flags.frank_caught],
    ['s1', flags.frank_offered_bookkeeping && !flags.frank_caught],
    ['s2', flags.frank_restrict_declared && !flags.frank_cracked],
    ['s3_pre', flags.frank_cracked && !flags.frank_invited_to_bedroom && !flags.frank_office_first_sex_done],
    ['s3_post', flags.frank_cracked && !flags.frank_invited_to_bedroom && flags.frank_office_first_sex_done],
    ['s4', flags.frank_invited_to_bedroom],
  ].filter(p => p[1]).map(p => p[0]),
}, null, 2);
